begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_function('public','get_flight_connection',array['uuid'],'Derived connection read exists');
insert into auth.users(id,email) select ('20100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'connection-'||n||'@example.invalid' from generate_series(1,6) n;
insert into public.memberships(user_id,role) select ('20100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=4 then 'admin' else 'member' end::public.member_role from generate_series(1,5) n;
insert into public.profiles(user_id,display_name,home_airport,pilot_designation) select ('20100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Connection pilot','KPAO','licensed' from generate_series(2,3) n;
insert into public.flights(id,owner_id,departure_airport,destination_airport,departure_at,departure_timezone,aircraft_description,pilot_places,visibility)
select ('20110000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'20100000-0000-4000-8000-000000000001','KPAO','KSQL',now()+interval '2 days','UTC','C172',2,case when n=6 then 'PRIVATE' else 'NETWORK' end::public.flight_visibility from generate_series(1,8) n;
update public.flights set departure_at=clock_timestamp()+interval '3 seconds' where id='20110000-0000-4000-8000-000000000008';
insert into public.flight_recipients(flight_id,user_id) values('20110000-0000-4000-8000-000000000006','20100000-0000-4000-8000-000000000002');
insert into public.flight_requests(id,flight_id,requester_id,introductory_note) select ('20120000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('20110000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'20100000-0000-4000-8000-000000000002','Private introduction must not appear in connection projection' from generate_series(1,8) n;
update public.flight_requests set status=case when id in ('20120000-0000-4000-8000-000000000001','20120000-0000-4000-8000-000000000006','20120000-0000-4000-8000-000000000007','20120000-0000-4000-8000-000000000008') then 'accepted'::public.flight_request_status when id='20120000-0000-4000-8000-000000000003' then 'declined'::public.flight_request_status when id='20120000-0000-4000-8000-000000000004' then 'withdrawn'::public.flight_request_status else 'cancelled'::public.flight_request_status end where id<>'20120000-0000-4000-8000-000000000002';
insert into public.flight_requests(flight_id,requester_id) values('20110000-0000-4000-8000-000000000001','20100000-0000-4000-8000-000000000003');
update public.flights set status='completed' where id='20110000-0000-4000-8000-000000000007';
create function pg_temp.actor(n integer) returns text language sql as $$select set_config('request.jwt.claims',json_build_object('sub',('20100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'role','authenticated','user_metadata',json_build_object('role','admin'))::text,true);$$;
create function pg_temp.connection(n integer default 1) returns jsonb language sql as $$select public.get_flight_connection(('20120000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid);$$;
select ok((select prosecdef and provolatile='s' and proconfig @> array['search_path=""'] from pg_proc where oid='public.get_flight_connection(uuid)'::regprocedure),'Connection read is stable with fixed definer path');
select ok(not has_function_privilege('anon','public.get_flight_connection(uuid)','EXECUTE'),'Anonymous execute denied');
select ok(not has_function_privilege('service_role','public.get_flight_connection(uuid)','EXECUTE'),'Service role execute denied');
set local role authenticated;
select set_config('request.jwt.claims','{}',true);
select is(pg_temp.connection(),null::jsonb,'Missing identity has no connection');
select pg_temp.actor(6);
select is(pg_temp.connection(),null::jsonb,'Missing membership cannot use metadata grant');
select pg_temp.actor(3);
select is(pg_temp.connection(),null::jsonb,'Pending pilot on same flight cannot access accepted pair');
select pg_temp.actor(4);
select is(pg_temp.connection(),null::jsonb,'Unrelated admin has no connection bypass');
select pg_temp.actor(1);
select is(pg_temp.connection(),'{"requestId":"20120000-0000-4000-8000-000000000001","flightId":"20110000-0000-4000-8000-000000000001","ownerId":"20100000-0000-4000-8000-000000000001","requesterId":"20100000-0000-4000-8000-000000000002"}'::jsonb,'Actual owner reads minimal approved pair without profile prerequisite');
select pg_temp.actor(2);
select is(pg_temp.connection()->>'ownerId','20100000-0000-4000-8000-000000000001','Accepted requester reads owner relationship');
select is(pg_temp.connection(2),null::jsonb,'Pending request is not a connection');
select is(pg_temp.connection(3),null::jsonb,'Declined request is not a connection');
select is(pg_temp.connection(4),null::jsonb,'Withdrawn request is not a connection');
select is(pg_temp.connection(5),null::jsonb,'Cancelled request is not a connection');
select is(pg_temp.connection(99),null::jsonb,'Missing request shares no-connection result');
select is(public.get_flight_connection(null),null::jsonb,'Null request shares no-connection result');
select is(pg_temp.connection(7),null::jsonb,'Completed flight has no active connection');
select is(pg_temp.connection(6)->>'requesterId','20100000-0000-4000-8000-000000000002','Current selected private participant has connection');
reset role;
select pg_sleep(greatest(0,extract(epoch from departure_at-clock_timestamp()))+0.01) from public.flights where id='20110000-0000-4000-8000-000000000008';
set local role authenticated;
select is(pg_temp.connection(8)->>'flightId','20110000-0000-4000-8000-000000000008','Past departure alone does not erase accepted connection');
reset role;
create temporary table request_snapshot as select to_jsonb(r) row from public.flight_requests r where flight_id::text like '20110000%';
delete from public.profiles where user_id='20100000-0000-4000-8000-000000000002';
set local role authenticated;
select is(pg_temp.connection()->>'requestId','20120000-0000-4000-8000-000000000001','Profile removal alone does not erase existing approval');
reset role;
select results_eq($$select to_jsonb(r) from public.flight_requests r where flight_id::text like '20110000%' order by id$$,$$select row from request_snapshot order by row->>'id'$$,'Connection reads do not mutate retained requests');
insert into public.profiles(user_id,display_name,home_airport,pilot_designation) values('20100000-0000-4000-8000-000000000002','Connection pilot','KPAO','licensed');
update public.memberships set status='disabled',disabled_at=now(),disabled_reason='Fixture' where user_id='20100000-0000-4000-8000-000000000002';
set local role authenticated;
select is(pg_temp.connection(),null::jsonb,'Disabled requester cannot read connection');
select pg_temp.actor(1);
select is(pg_temp.connection(),null::jsonb,'Owner cannot use disabled counterpart as an active connection');
reset role;
update public.memberships set status='active',disabled_at=null,disabled_reason=null where user_id='20100000-0000-4000-8000-000000000002';
update public.memberships set status='disabled',disabled_at=now(),disabled_reason='Fixture' where user_id='20100000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.actor(2);
select is(pg_temp.connection(),null::jsonb,'Disabled owner ends active connection access for requester');
reset role;
update public.memberships set status='active',disabled_at=null,disabled_reason=null where user_id='20100000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.actor(1);
select public.change_flight_recipient('20110000-0000-4000-8000-000000000006','20100000-0000-4000-8000-000000000002',false);
select is(pg_temp.connection(6),null::jsonb,'Removal closes derived connection for owner');
select pg_temp.actor(2);
select is(pg_temp.connection(6),null::jsonb,'Removal closes derived connection for requester');
select is((select status::text from public.flight_requests where id='20120000-0000-4000-8000-000000000006'),'cancelled','Requester still reads retained cancelled history');
select public.withdraw_flight_request('20110000-0000-4000-8000-000000000001','20120000-0000-4000-8000-000000000001');
select is(pg_temp.connection(),null::jsonb,'Accepted withdrawal immediately removes connection');
select public.submit_flight_interest('20110000-0000-4000-8000-000000000001');
select is(pg_temp.connection(),null::jsonb,'Resubmission does not revive approval');
select pg_temp.actor(1);
select public.decide_flight_request('20110000-0000-4000-8000-000000000001','20120000-0000-4000-8000-000000000001','accepted');
select is(pg_temp.connection()->>'requestId','20120000-0000-4000-8000-000000000001','Fresh owner approval derives same request connection');
select public.cancel_flight('20110000-0000-4000-8000-000000000001');
select is(pg_temp.connection(),null::jsonb,'Flight cancellation removes active connection');
select * from finish();
rollback;
